css:
.stratcraft-sim-container {
    padding: 28px;
    background: #f4f6fa;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #1a2744;
}

.stratcraft-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2b3d63 100%);
    color: #f4f6fa;
    border-radius: 4px;
    padding: 28px 32px;
    margin-bottom: 24px;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    flex-wrap: wrap;
    gap: 20px;
    border-left: 6px solid #c9a34a;
}
.stratcraft-sim-header-brand { flex: 1 1 60%; min-width: 280px; }
.stratcraft-sim-brand-tag {
    display: inline-block;
    font-size: 0.72rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: #dcc07d;
    margin-bottom: 8px;
    font-weight: 600;
}
.stratcraft-sim-header h1 {
    font-size: 1.55rem;
    font-weight: 600;
    margin: 0 0 6px 0;
    letter-spacing: 0.01em;
}
.stratcraft-sim-subtitle {
    margin: 0;
    color: #d6dfee;
    font-size: 0.92rem;
    font-style: italic;
}
.stratcraft-sim-period-counter {
    background: rgba(201,163,74,0.16);
    border: 1px solid rgba(201,163,74,0.55);
    padding: 10px 18px;
    border-radius: 4px;
    font-size: 0.95rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #f4e7c6;
    font-weight: 500;
}
.stratcraft-sim-period-counter span { margin: 0 3px; }

.stratcraft-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.stratcraft-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #cbd4e3;
    border-top: 3px solid #1a2744;
    border-radius: 4px;
    padding: 20px 22px;
    box-shadow: 0 1px 3px rgba(26,39,68,0.08);
}
.stratcraft-sim-kpi-score { border-top-color: #2f4a8f; }
.stratcraft-sim-kpi-approval { border-top-color: #1a2744; }
.stratcraft-sim-kpi-coherence { border-top-color: #2d7a63; }
.stratcraft-sim-kpi-resilience { border-top-color: #a8402a; }
.stratcraft-sim-kpi-archetype { border-top-color: #7f6318; }
.stratcraft-sim-kpi-label {
    color: #5c6880;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
    font-weight: 600;
}
.stratcraft-sim-kpi-value {
    font-size: 2.3rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
    margin-bottom: 4px;
}
.stratcraft-sim-kpi-value-sm { font-size: 1.2rem; font-weight: 600; }
.stratcraft-sim-kpi-score .stratcraft-sim-kpi-value { color: #2f4a8f; }
.stratcraft-sim-kpi-coherence .stratcraft-sim-kpi-value { color: #26654f; }
.stratcraft-sim-kpi-resilience .stratcraft-sim-kpi-value { color: #a8402a; }
.stratcraft-sim-kpi-archetype .stratcraft-sim-kpi-value { color: #7f6318; }
.stratcraft-sim-kpi-sub {
    color: #5e6a80;
    font-size: 0.76rem;
    font-style: italic;
}

.stratcraft-sim-workspace {
    display: grid;
    grid-template-columns: 1.15fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
    align-items: start;
}
.stratcraft-sim-briefing {
    background: #ffffff;
    border: 1px solid #cbd4e3;
    border-left: 4px solid #1a2744;
    border-radius: 4px;
    padding: 24px 26px;
}
.stratcraft-sim-briefing-phase {
    font-size: 0.74rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #7f6318;
    font-weight: 700;
    margin-bottom: 10px;
}
.stratcraft-sim-briefing h2 {
    font-size: 1.2rem;
    color: #1a2744;
    margin: 0 0 12px 0;
    font-weight: 600;
}
.stratcraft-sim-briefing-body {
    color: #33405a;
    font-size: 0.95rem;
    line-height: 1.55;
    margin: 0;
}
.stratcraft-sim-briefing-body p { margin: 0 0 10px 0; }
.stratcraft-sim-briefing-body p:last-child { margin-bottom: 0; }

.stratcraft-sim-debrief-score {
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-wrap: wrap;
    margin: 4px 0 14px 0;
    padding: 14px 16px;
    background: #eef1f7;
    border-left: 4px solid #2f4a8f;
    border-radius: 3px;
}
.stratcraft-sim-debrief-num {
    font-size: 2.1rem;
    font-weight: 700;
    color: #2f4a8f;
    line-height: 1;
}
.stratcraft-sim-debrief-tier {
    font-size: 0.95rem;
    font-weight: 600;
    color: #1a2744;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.stratcraft-sim-debrief-metrics {
    font-size: 0.82rem;
    color: #5c6880;
    width: 100%;
}
.stratcraft-sim-debrief-heading {
    font-size: 0.76rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #5c6880;
    font-weight: 700;
    margin: 16px 0 8px 0;
}
.stratcraft-sim-debrief-list {
    margin: 0;
    padding-left: 20px;
    color: #33405a;
    font-size: 0.9rem;
    line-height: 1.5;
}
.stratcraft-sim-debrief-list li { margin-bottom: 7px; }

.stratcraft-sim-controls {
    background: #ffffff;
    border: 1px solid #cbd4e3;
    border-radius: 4px;
    padding: 24px 26px;
}
.stratcraft-sim-controls h3 {
    font-size: 0.82rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #5c6880;
    font-weight: 700;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 1px solid #dde3ee;
}
.stratcraft-sim-decision-block, .stratcraft-sim-rationale-block {
    margin-bottom: 16px;
}
.stratcraft-sim-decision-block label, .stratcraft-sim-rationale-block label {
    display: block;
    font-size: 0.85rem;
    color: #1a2744;
    font-weight: 600;
    margin-bottom: 8px;
}
.stratcraft-sim-help {
    margin: 8px 0 0 0;
    font-size: 0.78rem;
    line-height: 1.45;
    color: #5c6880;
}

.stratcraft-sim-select {
    background: #ffffff;
    border: 1px solid #818da5;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.stratcraft-sim-select:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 3px rgba(26,39,68,0.22);
}
.stratcraft-sim-select:focus-visible {
    outline: 3px solid #2f4a8f;
    outline-offset: 2px;
}
.stratcraft-sim-select:disabled {
    background: #eef1f7;
    color: #5c6880;
    border-color: #b3bccd;
    cursor: not-allowed;
}
.stratcraft-sim-select option {
    background: #ffffff;
    color: #1a2744;
}
.stratcraft-sim-select option:disabled { color: #5e6a80; }

.stratcraft-sim-button-row {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-top: 8px;
}
.stratcraft-sim-primary-btn {
    background: #1a2744;
    color: #ffffff;
    border: 1px solid #1a2744;
    padding: 10px 22px;
    font-weight: 600;
    font-size: 0.9rem;
    letter-spacing: 0.04em;
    border-radius: 3px;
    min-height: 44px;
    transition: background 0.2s ease, transform 0.15s ease;
}
.stratcraft-sim-primary-btn:hover {
    background: #2b3d63;
    color: #ffffff;
    transform: translateY(-1px);
}
.stratcraft-sim-primary-btn:disabled,
.stratcraft-sim-primary-btn[disabled] {
    background: #616d85;
    border-color: #616d85;
    color: #ffffff;
    cursor: not-allowed;
    transform: none;
    opacity: 1;
}
.stratcraft-sim-controls .btn-outline-secondary {
    border-color: #818da5;
    color: #5c6880;
    background: #ffffff;
    font-size: 0.82rem;
    padding: 8px 16px;
    min-height: 44px;
}
.stratcraft-sim-controls .btn-outline-secondary:hover {
    background: #eef1f7;
    color: #1a2744;
    border-color: #5c6880;
}
.stratcraft-sim-container button:focus-visible {
    outline: 3px solid #2f4a8f;
    outline-offset: 2px;
}

.stratcraft-sim-history-zone, .stratcraft-sim-chart-zone {
    background: #ffffff;
    border: 1px solid #cbd4e3;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 20px;
}
.stratcraft-sim-history-zone h3, .stratcraft-sim-chart-zone h3 {
    font-size: 0.82rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #5c6880;
    font-weight: 700;
    margin: 0 0 14px 0;
}
.stratcraft-sim-table-scroll { overflow-x: auto; }
.stratcraft-sim-history-zone table {
    font-size: 0.86rem;
    color: #1a2744;
    margin-bottom: 0;
    min-width: 640px;
}
.stratcraft-sim-history-zone table thead th {
    background: #eef1f7;
    color: #1a2744;
    font-weight: 600;
    font-size: 0.74rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-bottom: 2px solid #7f6318;
    white-space: nowrap;
}
.stratcraft-sim-history-zone table td { vertical-align: middle; }

.stratcraft-sim-chart-zone canvas {
    max-height: 300px;
}

@media (max-width: 768px) {
    .stratcraft-sim-container { padding: 16px; }
    .stratcraft-sim-header {
        flex-direction: column;
        align-items: flex-start;
        padding: 20px;
    }
    .stratcraft-sim-header h1 { font-size: 1.2rem; }
    .stratcraft-sim-workspace { grid-template-columns: 1fr; }
    .stratcraft-sim-kpi-grid { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }
    .stratcraft-sim-kpi-value { font-size: 1.8rem; }
    .stratcraft-sim-briefing, .stratcraft-sim-controls { padding: 18px 18px; }
}

@media (prefers-reduced-motion: reduce) {
    .stratcraft-sim-container *,
    .stratcraft-sim-container *::before,
    .stratcraft-sim-container *::after {
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        scroll-behavior: auto !important;
    }
    .stratcraft-sim-primary-btn:hover { transform: none; }
}

js:
/* EQIL guard 1.3 (2026-10-08). Shared block, identical in every sim except SEED and MODE.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   8. (1.2) Text the sim wrote from its own translation table follows the language: after a switch, and whenever
      the sim writes text, a string from another language's table becomes the same key's string in the current one.
   9. (1.2) Randomness drawn while initialising or scoring comes from a generator kept in domainState, so undoing
      a round and submitting it again replays it exactly instead of re-rolling it.
  10. (1.2) Once the run is complete the submit button is disabled; an undo that reopens the run enables it again.
  11. (1.3) A choice keeps its order only when its texts read as a scale (a leading number, %, currency, or two level
      words). Numeric option values alone no longer count: many decisions with named options use 0, 1, 2 as values.
  12. (1.3) The seeded order also depends on the round, so options rebuilt each round are not in the same order
      every round. The same round (a redraw, a language switch, an undo, a resumed game) keeps its order.
   Reviews: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md,
   2026-10/EQIL_Portfolio_Finding_model-sweep_2026-10-06.md (EQIL v1.2.0 §15, gates G-F and G-H) */
var __eqilGuard = (function () {
    var SEED = "282";
    var MODE = "blank";   // blank: the sim addresses options by position, so no inserted placeholder and no shuffle; empty: placeholder and seeded shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        // 1.3: the round is part of the key, so a select rebuilt every round with the same id and values gets a new
        // order each round (1422 kept one order for all 9 rounds, so always picking the second option scored 88)
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + roundKey() + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
    function ordinal(texts, values) {
        // 1.3: only the texts decide. Numeric values alone (0, 1, 2) no longer keep a decision in order: many
        // decisions with named options use them, and a fixed order there let the first or last option win.
        var nt = 0, lv = 0;
        for (var i = 0; i < texts.length; i++) {
            var t = String(texts[i]).trim().toLowerCase(), c = t.charAt(0);
            if ((c >= "0" && c <= "9") || c === "$" || c === "€" || c === "£" || c === "+" || c === "-" || t.indexOf("%") >= 0) { nt++; }
            for (var k = 0; k < LEVEL.length; k++) { if (t.indexOf(LEVEL[k]) === 0) { lv++; break; } }
        }
        return nt * 2 >= texts.length || lv >= 2;
    }
    var PH_WORDS = ["select", "selec", "elig", "elij", "escog", "escoj", "choose", "pick one", "tria ", "escolh", "choisi"];
    function isPlaceholder(o) {
        if (o.value === "") { return true; }
        var t = String(o.textContent || "").trim().toLowerCase(), c = t.charAt(0), k;
        if (!(c === "-" || c === "—" || c === "–" || c === "." || c === "…")) { return false; }
        for (k = 0; k < PH_WORDS.length; k++) { if (t.indexOf(PH_WORDS[k]) >= 0) { return true; } }
        for (k = 0; k < t.length; k++) { if ("-—–.… ".indexOf(t.charAt(k)) < 0) { return false; } }
        return true;
    }
    function clear(sel, ph) {
        if (ph) { sel.value = ph.value; } else { sel.selectedIndex = -1; }
    }
    function hasValue(sel, v) {
        for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].value === v) { return true; } }
        return false;
    }

    /* 8. Text follows the language. The tables are the sim's own (vcI18n on the platform, .trans in the
       Open player). A string is replaced only when it is another language's value for a key the current
       language also has, and never when it is also a value of the current language itself. */
    var trCache = { lang: null, maps: null };
    function rawLang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        return String(l).toLowerCase().slice(0, 2);
    }
    function tables() {
        try { if (window.vcI18n && window.vcI18n._translations && typeof window.vcI18n._translations === "object") { var t = window.vcI18n._translations; for (var k in t) { if (t[k] && typeof t[k] === "object") { return t; } } } } catch (e) {}
        try { var f = sim(); if (f && f.trans && typeof f.trans === "object") { return f.trans; } } catch (e) {}
        return null;
    }
    function flat(o, pre, out, d) {
        if (!o || typeof o !== "object" || d > 4) { return out; }
        for (var k in o) {
            if (!Object.prototype.hasOwnProperty.call(o, k)) { continue; }
            var v = o[k];
            if (typeof v === "string") { out[pre + k] = v; }
            else if (v && typeof v === "object" && !Array.isArray(v)) { flat(v, pre + k + ".", out, d + 1); }
        }
        return out;
    }
    function squash(s) { return String(s).replace(/\s+/g, " ").replace(/^ | $/g, ""); }
    var decoder = null;
    function decode(s) {
        if (s.indexOf("&") < 0) { return s; }
        try { decoder = decoder || document.createElement("textarea"); decoder.innerHTML = s; return decoder.value; } catch (e) { return s; }
    }
    // a value with inline markup is several text nodes on the page: one piece per stretch between tags
    function pieces(v) {
        var p = String(v).split(/<[^>]*>/);
        for (var i = 0; i < p.length; i++) { p[i] = decode(p[i]); }
        return p;
    }
    var LETTER = /[A-Za-zÀ-ɏ]/;
    function quote(s) { return s.replace(/[.*+?^$()|[\]\\]/g, "\\$&"); }
    function template(a, b) {
        var parts = a.split(/\{(\w+)\}/), names = [], rx = "", lit = 0;
        for (var i = 0; i < parts.length; i++) {
            if (i % 2) { names.push(parts[i]); rx += (i === parts.length - 2 && parts[i + 1] === "") ? "([^\\s.,;:!?)]+)" : "(.+?)"; }
            else { rx += quote(parts[i]); lit += parts[i].replace(/\s/g, "").length; }
        }
        if (!names.length || lit < 10) { return null; }
        try { return { rx: new RegExp(rx), names: names, to: b }; } catch (e) { return null; }
    }
    function buildMaps(L) {
        var T = tables();
        if (!T || !T[L] || typeof T[L] !== "object") { return null; }
        var to = flat(T[L], "", {}, 0), own = {}, exact = {}, longs = [], tpls = [], k, j, P;
        for (k in to) {
            if (!Object.prototype.hasOwnProperty.call(to, k)) { continue; }
