        initialize(state) {
            if (!state || typeof state !== 'object') return;
            var hist = (state.history && state.history.length) ? state.history : [];
            var ds = state.domainState;
            var fresh = !ds || typeof ds !== 'object' || !ds.archetypeTally || hist.length === 0;
            if (fresh) {
                state.domainState = {
                    boardApproval: 50,
                    coherenceShare: 0,
                    coherenceScore: 0,
                    resilience: 0,
                    planQuality: 0,
                    qualitySum: 0,
                    qualityCount: 0,
                    archetypeTally: { innovation: 0, cost: 0, niche: 0, blue_ocean: 0 },
                    dominantArchetype: 'undefined',
                    diagnosis: null,
                    intent: null,
                    pillar1: null,
                    pillar2: null,
                    concentration: null,
                    wargameScores: {},
                    wargameMin: 0,
                    exposedWeakness: null,
                    revisionFit: null,
                    highConfCalls: 0,
                    badHighConfCalls: 0,
                    complete: false,
                    approvalHistory: [],
                    coherenceHistory: [],
                    resilienceHistory: [],
                    scoreHistory: [],
                    performance: { overallScore: 0, key: 'perf_weak', label: '' }
                };
            }
            this._ensureShape(state.domainState);
            if (!state.decisions || typeof state.decisions !== 'object') state.decisions = {};
            if (CONF_KEYS.indexOf(state.decisions.confidence) < 0) state.decisions.confidence = 'mid';
            state.decisions.choice = '';
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            if (!decisions || typeof decisions !== 'object') return false;
            var doc = (typeof document !== 'undefined') ? document : null;
            var sel = doc ? doc.getElementById('decisionSelect') : null;
            var conf = doc ? doc.getElementById('rationaleSelect') : null;
            if (sel) decisions.choice = sel.value;
            if (conf && conf.value) decisions.confidence = conf.value;
            if (CONF_KEYS.indexOf(decisions.confidence) < 0) decisions.confidence = 'mid';

            var state = this._liveState();
            var ds = (state && state.domainState) ? state.domainState : null;
            if (ds && ds.complete) {
                this._notify(this._t('warn_complete'), 'info');
                return false;
            }
            var round = this._round(state ? state.currentPeriod : 1);
            var ok = false;
            for (var i = 0; i < round.options.length; i++) {
                if (round.options[i].v === decisions.choice) ok = true;
            }
            if (!ok) {
                this._notify(this._t('decision_warning'), 'warning');
                return false;
            }
            decisions.roundId = round.id;
            return true;
        }

        calculateResults(state) {
            var ds = state.domainState;
            this._ensureShape(ds);
            var period = state.currentPeriod || 1;
            var maxP = state.maxPeriods || this.ROUNDS.length;
            var round = this._round(period);
            var opt = this._option(round, state.decisions ? state.decisions.choice : null);
            var conf = (state.decisions && CONF_KEYS.indexOf(state.decisions.confidence) >= 0)
                ? state.decisions.confidence : 'mid';

            // Everything below is scored against the state as it stood BEFORE this
            // round, so alignment can never be self-fulfilling.
            var quality = this._roundQuality(round, opt, ds);
            var wgScore = null;
            var deltaRes = 0;
            var prevResilience = ds.resilience;

            if (round.scorer === 'wargame') {
                var raw = this._wargameRaw(round.id, opt, ds);
                var adj = raw - 45;
                if (adj >= 0) adj *= (conf === 'high' ? 1.25 : (conf === 'low' ? 0.80 : 1));
                else adj *= (conf === 'high' ? 1.35 : (conf === 'low' ? 0.80 : 1));
                wgScore = r0(clamp(45 + adj, 0, 100));
                ds.wargameScores[round.id] = wgScore;
            }

            if (round.id === 'diagnosis') ds.diagnosis = opt.v;
            if (round.setsIntent) ds.intent = opt.arch;
            if (round.setsPillar === 1) ds.pillar1 = opt.arch;
            if (round.setsPillar === 2) ds.pillar2 = opt.arch;
            if (opt.conc) ds.concentration = opt.conc;
            if (round.scorer === 'revision') {
                ds.revisionFit = (opt.fixes === null)
                    ? (ds.wargameMin >= 70)
                    : (opt.fixes === ds.exposedWeakness);
            }

            if (round.commits && opt.arch) {
                ds.archetypeTally[opt.arch] = (ds.archetypeTally[opt.arch] || 0) + 1;
            }
            ds.coherenceShare = this._coherenceShare(ds.archetypeTally);
            ds.coherenceScore = r0(this._coherenceScore(ds.coherenceShare));
            ds.dominantArchetype = this._dominant(ds.archetypeTally);

            var deltaBA = this._applyApproval(ds, quality, conf);

            if (conf === 'high') {
                ds.highConfCalls += 1;
                if (quality < 5) ds.badHighConfCalls += 1;
            }

            this._refreshWargame(ds);
            deltaRes = r0(ds.resilience) - r0(prevResilience);

            ds.qualitySum += quality;
            ds.qualityCount += 1;
            ds.planQuality = r0((ds.qualitySum / ds.qualityCount) * 10);

            var overall = this._overall(ds);
            var tierKey = this._tierKey(overall);
            ds.performance = { overallScore: overall, key: tierKey, label: this._t(tierKey) };

            ds.complete = (period >= maxP);

            ds.approvalHistory.push(r0(ds.boardApproval));
            ds.coherenceHistory.push(ds.coherenceScore);
            ds.resilienceHistory.push(r0(ds.resilience));
            ds.scoreHistory.push(overall);

            var self = this;
            var nextPeriod = ds.complete ? period : (period + 1);
            if (typeof setTimeout === 'function') {
                setTimeout(function () {
                    self._updateBriefing({ currentPeriod: nextPeriod, maxPeriods: maxP, domainState: ds });
                }, 400);
            }

            return {
                period: period,
                round: round.id,
                choice: opt.v,
                archetype: opt.arch || 'none',
                quality: Math.round(quality * 10) / 10,
                confidence: conf,
                deltaApproval: deltaBA,
                boardApproval: r0(ds.boardApproval),
                coherenceShare: ds.coherenceShare,
                coherence: ds.coherenceScore,
                resilience: r0(ds.resilience),
                wargameScore: wgScore,
                deltaResilience: deltaRes,
                dominant: ds.dominantArchetype,
                planQuality: ds.planQuality,
                overallScore: overall,
                performanceKey: tierKey,
                complete: ds.complete
