        _ensureShape(ds) {
            if (!ds || typeof ds !== 'object') return;
            var nums = {
                boardApproval: 50, coherenceShare: 0, coherenceScore: 0, resilience: 0,
                planQuality: 0, qualitySum: 0, qualityCount: 0, wargameMin: 0,
                highConfCalls: 0, badHighConfCalls: 0
            };
            for (var k in nums) {
                if (typeof ds[k] !== 'number' || isNaN(ds[k])) ds[k] = nums[k];
            }
            if (!ds.archetypeTally || typeof ds.archetypeTally !== 'object') {
                ds.archetypeTally = { innovation: 0, cost: 0, niche: 0, blue_ocean: 0 };
            }
            for (var i = 0; i < ARCH_KEYS.length; i++) {
                if (typeof ds.archetypeTally[ARCH_KEYS[i]] !== 'number') ds.archetypeTally[ARCH_KEYS[i]] = 0;
            }
            if (!ds.wargameScores || typeof ds.wargameScores !== 'object') ds.wargameScores = {};
            var arrs = ['approvalHistory', 'coherenceHistory', 'resilienceHistory', 'scoreHistory'];
            for (var j = 0; j < arrs.length; j++) {
                if (!Array.isArray(ds[arrs[j]])) ds[arrs[j]] = [];
            }
            if (!ds.dominantArchetype) ds.dominantArchetype = 'undefined';
            if (typeof ds.complete !== 'boolean') ds.complete = false;
            if (!ds.performance || typeof ds.performance !== 'object') {
                ds.performance = { overallScore: 0, key: 'perf_weak', label: '' };
            }
            if (typeof ds.performance.overallScore !== 'number') ds.performance.overallScore = 0;
        }

        _round(period) {
            var idx = clamp((period || 1) - 1, 0, this.ROUNDS.length - 1);
            return this.ROUNDS[Math.floor(idx)];
        }

        _option(round, choice) {
            for (var i = 0; i < round.options.length; i++) {
                if (round.options[i].v === choice) return round.options[i];
            }
            return round.options[0];
        }

        _affinity(intent, arch) {
            if (!intent || !arch) return 0;
            var row = AFFINITY[intent];
            if (!row) return 0;
            var v = row[arch];
            return (typeof v === 'number') ? v : 0;
        }

        _fitBonus(opt, diagnosis) {
            if (!opt.fit || !diagnosis) return 0;
            var v = opt.fit[diagnosis];
            return (typeof v === 'number') ? v : 0;
        }

        _coherenceShare(tally) {
            var total = 0, top = 0;
            for (var i = 0; i < ARCH_KEYS.length; i++) {
                var n = tally[ARCH_KEYS[i]] || 0;
                total += n;
                if (n > top) top = n;
            }
            return total > 0 ? Math.round((top / total) * 100) : 0;
        }

        _dominant(tally) {
            var top = 0, winners = [];
            for (var i = 0; i < ARCH_KEYS.length; i++) {
                var n = tally[ARCH_KEYS[i]] || 0;
                if (n > top) { top = n; winners = [ARCH_KEYS[i]]; }
                else if (n === top && n > 0) { winners.push(ARCH_KEYS[i]); }
            }
            if (top === 0) return 'undefined';
            return (winners.length > 1) ? 'contested' : winners[0];
        }

        // A plan with no dominant logic is a list of initiatives; a plan that
        // answers every question with the same archetype has no adaptive
        // capacity. The healthy band is 55 to 80 per cent.
        _coherenceScore(share) {
            if (share <= 0) return 0;
            if (share < 40) return clamp(share * 1.5, 0, 100);
            if (share < 55) return clamp(60 + (share - 40) * 2.67, 0, 100);
            if (share <= 80) return 100;
            return clamp(100 - (share - 80) * 2, 0, 100);
        }

        _coherenceBandKey(share) {
            if (share <= 0) return 'band_none';
            if (share < 40) return 'band_scattered';
            if (share < 55) return 'band_loose';
            if (share <= 80) return 'band_focused';
            return 'band_rigid';
        }

        _roundQuality(round, opt, ds) {
            var q = 6;
            switch (round.scorer) {
                case 'diagnosis':
                    q = opt.base;
                    break;
                case 'fit':
                    q = opt.base + this._fitBonus(opt, ds.diagnosis);
                    break;
                case 'affinity':
                    q = opt.base + this._affinity(ds.intent, opt.arch);
                    break;
                case 'complement':
                    var aff = this._affinity(ds.intent, opt.arch);
                    var bonus = (opt.arch !== ds.pillar1 && aff >= 1) ? 2 : 0;
                    q = opt.base + aff + bonus;
                    break;
                case 'allocation':
                    q = this._allocationQuality(opt, ds);
                    break;
                case 'wargame':
                    q = this._wargameRaw(round.id, opt, ds) / 10;
                    break;
                case 'revision':
                    q = this._revisionQuality(opt, ds);
                    break;
                default:
                    q = 6;
            }
            return clamp(q, 0, 10);
        }

        // Concentration is right when the plan already has a clear logic; keeping
        // optionality is right when it does not. The balanced split is the
        // no-choice choice and is never the best answer.
        _allocationQuality(opt, ds) {
            var s = ds.coherenceShare;
            if (opt.conc === 'high') return 5 + (s - 55) / 9;
            if (opt.conc === 'adaptive') return 5 + (55 - s) / 9;
            if (opt.conc === 'focused') return 6.5;
            return 4.5;
        }

        // War-game responses score on three things: whether the move is
        // structurally sound against THIS attacker, whether it exploits the
        // guiding policy, and whether the resource envelope supports it.
        _wargameRaw(roundId, opt, ds) {
            var intent = ds.intent || (ARCH_KEYS.indexOf(ds.dominantArchetype) >= 0 ? ds.dominantArchetype : null);
            var struct = 0;
            if (roundId === 'wg_incumbent') {
                if (opt.move === 'differentiate') struct = (intent === 'cost') ? -5 : 20;
                else if (opt.move === 'match_price') struct = (intent === 'cost') ? 18 : -15;
                else if (opt.move === 'lock_contracts') struct = 12 + ((intent === 'niche') ? 6 : 0);
                else struct = (intent === 'blue_ocean') ? 18 : ((intent === 'innovation') ? 8 : 2);
            } else if (roundId === 'wg_disruptor') {
                if (opt.move === 'cloud_native') struct = 20 + ((intent === 'innovation' || intent === 'blue_ocean') ? 6 : 0);
                else if (opt.move === 'fighter_brand') struct = 6 + ((intent === 'cost') ? 10 : 0);
                else if (opt.move === 'acquire') struct = (ds.concentration === 'high') ? 18 : -5;
                else struct = (intent === 'niche') ? 14 : -12;
            } else {
                var ba = ds.boardApproval;
                if (opt.move === 'engage') struct = (ba >= 65) ? 20 : -8;
                else if (opt.move === 'proxy_fight') struct = (ba >= 80) ? 16 : ((ba < 60) ? -25 : 0);
                else if (opt.move === 'concede') struct = 10;
                else struct = (ds.coherenceShare >= 60) ? 16 : -10;
            }
            var exploit = this._affinity(intent, opt.arch) * 3;
            var matches = (opt.arch === intent);
            var concMod = 0;
            if (ds.concentration === 'high') concMod = matches ? 8 : -10;
            else if (ds.concentration === 'focused') concMod = matches ? 4 : -4;
            else if (ds.concentration === 'balanced') concMod = -4;
            else if (ds.concentration === 'adaptive') concMod = matches ? -4 : 8;
            return clamp(45 + struct + exploit + concMod, 0, 100);
        }

        // The right final revision is the one that repairs the weakness the
        // war-game actually exposed. Staying the course is only defensible when
        // no scenario broke through.
        _revisionQuality(opt, ds) {
            var allStrong = (ds.wargameMin >= 70);
            if (opt.fixes === null) return allStrong ? 9 : 3.5;
            if (allStrong) return 6;
            return (opt.fixes === ds.exposedWeakness) ? 9 : 4.5;
        }

        // Board approval moves toward the level this round justifies, so a late
        // mistake still costs and a strong finish still pays.
        _applyApproval(ds, quality, conf) {
            var before = r0(ds.boardApproval);
            var target = 50 + (quality - 5.5) * 9;
            var disp = target - ds.boardApproval;
            if (disp >= 0) disp *= (conf === 'high' ? 1.25 : (conf === 'low' ? 0.75 : 1));
            else disp *= (conf === 'high' ? 1.40 : (conf === 'low' ? 0.75 : 1));
            ds.boardApproval = clamp(ds.boardApproval + disp * 0.20, 0, 100);
            return r0(ds.boardApproval) - before;
        }

        _refreshWargame(ds) {
            var vals = [], keys = [], i;
            for (i = 0; i < WG_IDS.length; i++) {
                var k = WG_IDS[i];
                if (typeof ds.wargameScores[k] === 'number') { vals.push(ds.wargameScores[k]); keys.push(k); }
            }
            if (!vals.length) {
                ds.resilience = 0; ds.wargameMin = 0; ds.exposedWeakness = null;
                return;
            }
            var sum = 0, min = vals[0], minKey = keys[0];
            for (i = 0; i < vals.length; i++) {
                sum += vals[i];
                if (vals[i] < min) { min = vals[i]; minKey = keys[i]; }
            }
            ds.resilience = sum / vals.length;
            ds.wargameMin = min;
            ds.exposedWeakness = minKey;
        }

        // Resilience is untested until war-gaming starts, so before round 7 the
        // score is the renormalised blend of the two metrics that do exist.
        _overall(ds) {
            var cs = this._coherenceScore(ds.coherenceShare);
            var started = false;
            for (var i = 0; i < WG_IDS.length; i++) {
                if (typeof ds.wargameScores[WG_IDS[i]] === 'number') started = true;
            }
            if (!started) return r0(clamp((0.40 * ds.boardApproval + 0.30 * cs) / 0.70, 0, 100));
            return r0(clamp(0.40 * ds.boardApproval + 0.30 * cs + 0.30 * ds.resilience, 0, 100));
        }

        _tierKey(score) {
            if (score >= 85) return 'perf_exemplary';
            if (score >= 70) return 'perf_strong';
            if (score >= 55) return 'perf_competent';
            if (score >= 40) return 'perf_developing';
            return 'perf_weak';
        }

        _archetypeLabel(key) {
            var map = {
                innovation: 'arch_innovation',
                cost: 'arch_cost',
                niche: 'arch_niche',
                blue_ocean: 'arch_blue',
                contested: 'arch_contested',
                none: 'arch_none'
