            var k = map[key];
            return k ? this._t(k) : this._t('archetype_undef');
        }

        _setText(id, value) {
            if (typeof document === 'undefined') return;
            var el = document.getElementById(id);
            if (el) el.textContent = value;
        }

        _setHTML(id, value) {
            if (typeof document === 'undefined') return;
            var el = document.getElementById(id);
            if (el) el.innerHTML = value;
        }

        _esc(s) {
            return String(s === undefined || s === null ? '' : s)
                .split('&').join('&amp;')
                .split('<').join('&lt;')
                .split('>').join('&gt;');
        }

        _updateBriefing(state) {
            if (typeof document === 'undefined') return;
            var live = this._liveState();
            var ds = (state && state.domainState) ? state.domainState
                : (live && live.domainState ? live.domainState : null);
            var maxP = (state && state.maxPeriods) || (live && live.maxPeriods) || this.ROUNDS.length;
            var period = (state && state.currentPeriod) || (live && live.currentPeriod) || 1;
            var done = !!(ds && ds.complete);
            var round = this._round(period);

            if (done) {
                this._setText('briefingPhase', this._t('phase_complete'));
                this._setText('briefingTitle', this._t('debrief_title'));
                this._setHTML('briefingText', this._debriefHTML(ds));
                this._setText('decisionLabel', this._t('debrief_label'));
            } else {
                this._setText('briefingPhase', this._t(round.phaseKey));
                this._setText('briefingTitle', this._t(round.titleKey));
                this._setHTML('briefingText', '<p>' + this._esc(this._t(round.descKey)) + '</p>');
                this._setText('decisionLabel', this._t(round.labelKey));
            }

            var sel = document.getElementById('decisionSelect');
            if (sel) {
                sel.innerHTML = '';
                if (done) {
                    var od = document.createElement('option');
                    od.value = '';
                    od.textContent = this._t('debrief_no_more');
                    if (od.setAttribute) od.setAttribute('disabled', 'disabled');
                    od.disabled = true;
                    sel.appendChild(od);
                    sel.value = '';
                    sel.disabled = true;
                } else {
                    sel.disabled = false;
                    var ph = document.createElement('option');
                    ph.value = '';
                    ph.textContent = this._t('choose_prompt');
                    if (ph.setAttribute) ph.setAttribute('disabled', 'disabled');
                    ph.disabled = true;
                    sel.appendChild(ph);
                    for (var i = 0; i < round.options.length; i++) {
                        var o = document.createElement('option');
                        o.value = round.options[i].v;
                        o.textContent = this._t(round.options[i].tKey);
                        sel.appendChild(o);
                    }
                    // Each round starts from an explicit, unmade choice so a plan
                    // can never be submitted by repeated clicking.
                    sel.value = '';
                }
            }

            var btn = document.getElementById('nextPeriodBtn');
            if (btn) {
                btn.disabled = !!done;
                btn.textContent = done ? this._t('completed_btn') : this._t('submit_btn');
            }
            var undo = document.getElementById('undoBtn');
            if (undo) undo.disabled = false;

            if (ds) {
                this._setText('archetypeDisplay', this._archetypeLabel(ds.dominantArchetype || 'undefined'));
                var intentLabel = ds.intent ? this._archetypeLabel(ds.intent) : this._t('archetype_sub');
                this._setText('archetypeSub', ds.intent
                    ? this._t('archetype_sub_set', { intent: intentLabel })
                    : this._t('archetype_sub'));
                var share = ds.coherenceShare || 0;
                this._setText('coherenceBand', share > 0
                    ? (this._t(this._coherenceBandKey(share)) + ' · ' + share + '%')
                    : this._t('band_none'));
                var sc = (ds.performance && ds.performance.overallScore) || 0;
                this._setText('scoreBand', sc > 0
                    ? this._t(this._tierKey(sc))
                    : this._t('score_sub'));
            }
        }

        _debriefHTML(ds) {
            if (!ds) return '';
            var score = (ds.performance && ds.performance.overallScore) || 0;
            var tier = this._t(this._tierKey(score));
            var out = '<div class="stratcraft-sim-debrief-score">';
            out += '<span class="stratcraft-sim-debrief-num">' + score + '</span>';
            out += '<span class="stratcraft-sim-debrief-tier">' + this._esc(tier) + '</span>';
            out += '<span class="stratcraft-sim-debrief-metrics">'
                + this._esc(this._t('debrief_metrics', {
                    board: r0(ds.boardApproval),
                    coherence: ds.coherenceScore,
                    share: ds.coherenceShare,
                    resilience: r0(ds.resilience)
                })) + '</span>';
            out += '</div>';
            out += '<p>' + this._esc(this._t('debrief_intro')) + '</p>';
            out += '<div class="stratcraft-sim-debrief-heading">' + this._esc(this._t('debrief_insights')) + '</div>';
            var ins = this._insights(ds);
            out += '<ul class="stratcraft-sim-debrief-list">';
            for (var i = 0; i < ins.length; i++) out += '<li>' + this._esc(ins[i]) + '</li>';
            out += '</ul>';
            return out;
        }

        _insights(ds) {
            var out = [];
            if (!ds) return out;
            var share = ds.coherenceShare || 0;
            if (share >= 55 && share <= 80) out.push(this._t('ins_coh_focused'));
            else if (share > 80) out.push(this._t('ins_coh_rigid'));
            else if (share >= 40) out.push(this._t('ins_coh_loose'));
            else out.push(this._t('ins_coh_scattered'));

            var res = r0(ds.resilience);
            if (res >= 75) out.push(this._t('ins_res_strong'));
            else if (res >= 50) out.push(this._t('ins_res_mixed'));
            else out.push(this._t('ins_res_weak'));

            if (ds.exposedWeakness) {
                out.push(this._t('ins_weakest', {
                    scenario: this._t('rn_' + ds.exposedWeakness),
                    score: ds.wargameMin
                }));
            }

            var ba = r0(ds.boardApproval);
            if (ba >= 70) out.push(this._t('ins_board_backs'));
            else if (ba < 45) out.push(this._t('ins_board_skeptical'));
            else out.push(this._t('ins_board_mixed'));

            if (ds.revisionFit === true) out.push(this._t('ins_revision_fit'));
            else if (ds.revisionFit === false) out.push(this._t('ins_revision_miss'));

            if (ds.diagnosis) {
                out.push(this._t('ins_diagnosis', { diagnosis: ds.diagnosis }));
            }
            if (ds.badHighConfCalls >= 2) out.push(this._t('ins_overconfident', { n: ds.badHighConfCalls }));
            else if (ds.highConfCalls === 0) out.push(this._t('ins_underconfident'));

            if (ds.concentration) out.push(this._t('ins_alloc_' + ds.concentration));
            return out;
        }

