        getChartData(state) {
            var ds = (state && state.domainState && typeof state.domainState === 'object') ? state.domainState : {};
            var sc = Array.isArray(ds.scoreHistory) ? ds.scoreHistory : [];
            var ap = Array.isArray(ds.approvalHistory) ? ds.approvalHistory : [];
            var co = Array.isArray(ds.coherenceHistory) ? ds.coherenceHistory : [];
            var re = Array.isArray(ds.resilienceHistory) ? ds.resilienceHistory : [];
            var n = Math.max(sc.length, ap.length, co.length, re.length);
            var labels = [];
            for (var i = 0; i < n; i++) labels.push('R' + (i + 1));
            return {
                trajectoryChart: {
                    labels: labels,
                    datasets: [{ data: sc }, { data: ap }, { data: co }, { data: re }]
                }
            };
        }

        getHint(state, results) {
            if (!results || typeof results !== 'object') return null;
            var ds = (state && state.domainState) ? state.domainState : {};
            var period = (state && state.currentPeriod) || results.period || 1;

            if (period === 1) return this._t('hint_r1', { diagnosis: results.choice });
            if (results.complete) return this._t('hint_final', { score: results.overallScore });
            if (results.quality <= 4) return this._t('hint_poor_fit');
            if (results.confidence === 'high' && results.deltaApproval < 0) return this._t('hint_overconfident');
            if (period >= 7 && period <= 9) {
                if (results.wargameScore !== null && results.wargameScore < 45) return this._t('hint_wg_weak');
                if (results.wargameScore !== null && results.wargameScore >= 75) return this._t('hint_wg_strong');
            }
            if (results.coherenceShare > 80 && period >= 5) return this._t('hint_rigid');
            if (results.coherenceShare > 0 && results.coherenceShare < 40 && period >= 5) return this._t('hint_incoherent');
            if (period === 6) return this._t('hint_alloc', { share: results.coherenceShare });
            if (results.quality >= 8) return this._t('hint_strong_fit');
            return null;
        }

