        getPerformanceSummary(history) {
            var hist = Array.isArray(history) ? history : [];
            if (!hist.length) {
                return {
                    periods: 0, overallScore: 0, totalScore: 0, score: 0, compositeScore: 0,
                    boardApproval: 0, strategicCoherence: 0, coherenceShare: 0, resilience: 0,
                    performanceKey: 'perf_weak', performanceLabel: this._t('perf_weak'),
                    performance: this._t('perf_weak'), insights: []
                };
            }
            var last = hist[hist.length - 1] || {};
            var ds = (last.domainState && typeof last.domainState === 'object') ? last.domainState : {};
            this._ensureShape(ds);
            var res = (last.results && typeof last.results === 'object') ? last.results : {};

            var overall = (typeof res.overallScore === 'number')
                ? res.overallScore
                : ((ds.performance && ds.performance.overallScore) || this._overall(ds));
            var key = this._tierKey(overall);
            var label = this._t(key);

            return {
                periods: hist.length,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                compositeScore: overall,
                boardApproval: r0(ds.boardApproval),
                strategicCoherence: ds.coherenceScore,
                coherenceShare: ds.coherenceShare,
                resilience: r0(ds.resilience),
                planQuality: ds.planQuality,
                dominantArchetype: this._archetypeLabel(ds.dominantArchetype || 'undefined'),
                exposedWeakness: ds.exposedWeakness ? this._t('rn_' + ds.exposedWeakness) : null,
                wargameScores: ds.wargameScores,
                performanceKey: key,
                performanceLabel: label,
                performance: label,
                insights: this._insights(ds)
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var label = s.performanceLabel || this._t(this._tierKey(score));
            var out = '<div class="stratcraft-sim-debrief-score">';
            out += '<span class="stratcraft-sim-debrief-num">' + score + '</span>';
            out += '<span class="stratcraft-sim-debrief-tier">' + this._esc(label) + '</span>';
            out += '<span class="stratcraft-sim-debrief-metrics">'
                + this._esc(this._t('debrief_metrics', {
                    board: s.boardApproval || 0,
                    coherence: s.strategicCoherence || 0,
                    share: s.coherenceShare || 0,
                    resilience: s.resilience || 0
                })) + '</span></div>';
            out += '<p>' + this._esc(this._t('debrief_intro')) + '</p>';
            var ins = Array.isArray(s.insights) ? s.insights : [];
